import { Ls as Vector3, Qr as Mesh, R as BoxGeometry } from "./three.core-BTfOrhf1.js";
import { NodeMaterial } from "./three_webgpu.js";
import { Fn, If, Loop, acos, add, cameraPosition, clamp, cos, dot, exp, float, floor, fract, max, min, mix, modelViewProjection, mul, normalize, positionWorld, pow, smoothstep, sub, time, uniform, varyingProperty, vec2, vec3, vec4 } from "./three_tsl.js";
//#region node_modules/three/examples/jsm/objects/SkyMesh.js
/**
* Represents a skydome for scene backgrounds. Based on [A Practical Analytic Model for Daylight](https://www.researchgate.net/publication/220720443_A_Practical_Analytic_Model_for_Daylight)
* aka The Preetham Model, the de facto standard for analytical skydomes.
*
* Note that this class can only be used with {@link WebGPURenderer}.
* When using {@link WebGLRenderer}, use {@link Sky}.
*
* More references:
*
* - {@link http://simonwallner.at/project/atmospheric-scattering/}
* - {@link http://blenderartists.org/forum/showthread.php?245954-preethams-sky-impementation-HDR}
*
* ```js
* const sky = new SkyMesh();
* sky.scale.setScalar( 10000 );
* scene.add( sky );
* ```
*
* It can be useful to hide the sun disc when generating an environment map to avoid artifacts
*
* ```js
* // disable before rendering environment map
* sky.showSunDisc.value = false;
* // ...
* // re-enable before scene sky box rendering
* sky.showSunDisc.value = true;
* ```
*
* @augments Mesh
* @three_import import { SkyMesh } from 'three/addons/objects/SkyMesh.js';
*/
var SkyMesh = class extends Mesh {
	/**
	* Constructs a new skydome.
	*/
	constructor() {
		const material = new NodeMaterial();
		super(new BoxGeometry(1, 1, 1), material);
		/**
		* The turbidity uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.turbidity = uniform(2);
		/**
		* The rayleigh uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.rayleigh = uniform(1);
		/**
		* The mieCoefficient uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.mieCoefficient = uniform(.005);
		/**
		* The mieDirectionalG uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.mieDirectionalG = uniform(.8);
		/**
		* The sun position uniform.
		*
		* @type {UniformNode<vec3>}
		*/
		this.sunPosition = uniform(new Vector3());
		/**
		* The cloud scale uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.cloudScale = uniform(2e-4);
		/**
		* The cloud speed uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.cloudSpeed = uniform(2e-5);
		/**
		* The cloud coverage uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.cloudCoverage = uniform(.4);
		/**
		* The cloud density uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.cloudDensity = uniform(.4);
		/**
		* The cloud elevation uniform.
		*
		* @type {UniformNode<float>}
		*/
		this.cloudElevation = uniform(.5);
		/**
		* Whether to render the solar disc.
		*
		* @type {UniformNode<float>}
		*/
		this.showSunDisc = uniform(1);
		/**
		* This flag can be used for type testing.
		*
		* @type {boolean}
		* @readonly
		* @default true
		* @deprecated Use isSkyMesh instead.
		*/
		this.isSky = true;
		/**
		* This flag can be used for type testing.
		*
		* @type {boolean}
		* @readonly
		* @default true
		*/
		this.isSkyMesh = true;
		const vSunDirection = varyingProperty("vec3");
		const vSunE = varyingProperty("float");
		const vBetaR = varyingProperty("vec3");
		const vBetaM = varyingProperty("vec3");
		const vertexNode = /*@__PURE__*/ Fn(() => {
			const e = float(2.718281828459045);
			const totalRayleigh = vec3(5804542996261093e-21, 13562911419845635e-21, 30265902468824876e-21);
			const MieConst = vec3(183999185144339.78, 277980239196605.28, 407904795438610.94);
			const cutoffAngle = float(1.6110731556870734);
			const steepness = float(1.5);
			const EE = float(1e3);
			const sunDirection = normalize(this.sunPosition);
			vSunDirection.assign(sunDirection);
			const angle = sunDirection.y;
			const zenithAngleCos = clamp(angle, -1, 1);
			const sunIntensity = EE.mul(max(0, float(1).sub(pow(e, cutoffAngle.sub(acos(zenithAngleCos)).div(steepness).negate()))));
			vSunE.assign(sunIntensity);
			const sunfade = float(1).sub(clamp(float(1).sub(exp(this.sunPosition.y.div(45e4))), 0, 1));
			const rayleighCoefficient = this.rayleigh.sub(float(1).mul(float(1).sub(sunfade)));
			vBetaR.assign(totalRayleigh.mul(rayleighCoefficient));
			const c = float(.2).mul(this.turbidity).mul(1e-17);
			const totalMie = float(.434).mul(c).mul(MieConst);
			vBetaM.assign(totalMie.mul(this.mieCoefficient));
			const position = modelViewProjection;
			position.z.assign(position.w);
			return position;
		})();
		const colorNode = /*@__PURE__*/ Fn(() => {
			const pi = float(3.141592653589793);
			const rayleighZenithLength = float(8400);
			const mieZenithLength = float(1250);
			const sunAngularDiameterCos = float(.9999566769464484);
			const THREE_OVER_SIXTEENPI = float(.05968310365946075);
			const ONE_OVER_FOURPI = float(.07957747154594767);
			const direction = normalize(positionWorld.sub(cameraPosition));
			const zenithAngle = acos(max(0, direction.y));
			const inverse = float(1).div(cos(zenithAngle).add(float(.15).mul(pow(float(93.885).sub(zenithAngle.mul(180).div(pi)), -1.253))));
			const sR = rayleighZenithLength.mul(inverse);
			const sM = mieZenithLength.mul(inverse);
			const Fex = exp(mul(vBetaR, sR).add(mul(vBetaM, sM)).negate());
			const cosTheta = dot(direction, vSunDirection);
			const c = cosTheta.mul(.5).add(.5);
			const rPhase = THREE_OVER_SIXTEENPI.mul(float(1).add(pow(c, 2)));
			const betaRTheta = vBetaR.mul(rPhase);
			const g2 = pow(this.mieDirectionalG, 2);
			const inv = float(1).div(pow(float(1).sub(float(2).mul(this.mieDirectionalG).mul(cosTheta)).add(g2), 1.5));
			const mPhase = ONE_OVER_FOURPI.mul(float(1).sub(g2)).mul(inv);
			const betaMTheta = vBetaM.mul(mPhase);
			const Lin = pow(vSunE.mul(add(betaRTheta, betaMTheta).div(add(vBetaR, vBetaM))).mul(sub(1, Fex)), vec3(1.5));
			Lin.mulAssign(mix(vec3(1), pow(vSunE.mul(add(betaRTheta, betaMTheta).div(add(vBetaR, vBetaM))).mul(Fex), vec3(1 / 2)), clamp(pow(sub(1, vSunDirection.y), 5), 0, 1)));
			const L0 = vec3(.1).mul(Fex);
			const sundisc = clamp(cosTheta.sub(sunAngularDiameterCos).mul(5e4), 0, 1).mul(this.showSunDisc);
			const sundiscColor = min(vSunE.mul(Fex), 80).mul(760).mul(sundisc);
			const texColor = add(Lin, L0).mul(.04).add(sundiscColor).add(vec3(0, 3e-4, 75e-5)).toVar();
			const gradient = Fn(([i]) => {
				const p = fract(i.xyx.mul(vec3(.1031, .103, .0973))).toVar();
				p.addAssign(dot(p, p.yzx.add(33.33)));
				return fract(p.xx.add(p.yz).mul(p.zy)).mul(2).sub(1);
			});
			const noise = Fn(([p]) => {
				const i = floor(p);
				const f = fract(p);
				const u = f.mul(f).mul(f).mul(f.mul(f.mul(6).sub(15)).add(10));
				const a = dot(gradient(i), f);
				const b = dot(gradient(i.add(vec2(1, 0))), f.sub(vec2(1, 0)));
				const c = dot(gradient(i.add(vec2(0, 1))), f.sub(vec2(0, 1)));
				const d = dot(gradient(i.add(vec2(1, 1))), f.sub(vec2(1, 1)));
				return mix(mix(a, b, u.x), mix(c, d, u.x), u.y).mul(1.6);
			});
			const fbm = Fn(([position, drift]) => {
				const p = vec2(position).toVar();
				const result = float(0).toVar();
				const amplitude = float(1).toVar();
				Loop(4, () => {
					result.addAssign(amplitude.mul(noise(p)));
					amplitude.mulAssign(.5);
					p.mulAssign(2).addAssign(drift);
				});
				return result;
			});
			If(direction.y.greaterThan(0).and(this.cloudCoverage.greaterThan(0)), () => {
				const elevation = mix(1, .1, this.cloudElevation);
				const cloudUV = direction.xz.div(direction.y.mul(elevation)).toVar();
				cloudUV.mulAssign(this.cloudScale);
				cloudUV.addAssign(time.mul(this.cloudSpeed));
				const evolve = time.mul(this.cloudSpeed).mul(300);
				const cloudNoise = fbm(cloudUV.mul(1e3), evolve).mul(.7).add(.5).clamp(0, 1).toVar();
				const region = noise(cloudUV.mul(300)).mul(.37).add(.5);
				const cov = clamp(this.cloudCoverage.add(region.sub(.5).mul(.6)), 0, 1);
				const threshold = sub(1, cov).toVar();
				const cloudMask = smoothstep(threshold, threshold.add(.3), cloudNoise).toVar();
				const horizonFade = smoothstep(0, add(.03, mul(.06, this.cloudElevation)), direction.y);
				cloudMask.mulAssign(horizonFade);
				const dayFactor = smoothstep(-.08, .3, vSunDirection.y);
				const sunColor = vSunE.mul(Fex).mul(.22).mul(.04).toVar();
				const skyAmbient = Lin.mul(.04).add(vec3(0, 3e-4, 75e-5));
				const depth = max(0, cloudNoise.sub(threshold)).toVar();
				const beer = exp(depth.mul(-4)).toVar();
				const powder = sub(1, beer.mul(beer));
				const shade = mix(.45, 1, beer.mul(powder).mul(2.6).clamp(0, 1));
				const silver = float(.51).div(pow(sub(1.49, cosTheta.mul(1.4)), 1.5)).clamp(0, 3);
				const edge = cloudMask.mul(sub(1, cloudMask)).mul(4);
				const cloudColor = skyAmbient.add(sunColor.mul(shade)).toVar();
				cloudColor.addAssign(sunColor.mul(silver).mul(edge).mul(.6));
				cloudColor.mulAssign(dayFactor.max(.03));
				const alpha = sub(1, exp(depth.mul(this.cloudDensity).mul(-12))).mul(horizonFade).toVar();
				texColor.subAssign(L0.mul(.04).add(sundiscColor).mul(alpha));
				const cloudAerial = mix(texColor, cloudColor, Fex);
				texColor.assign(mix(texColor, cloudAerial, alpha));
			});
			return vec4(texColor, 1);
		})();
		material.side = 1;
		material.depthWrite = false;
		material.fog = false;
		material.vertexNode = vertexNode;
		material.colorNode = colorNode;
	}
};
//#endregion
export { SkyMesh };
